<script setup lang="ts">
import {computed,ref} from 'vue'
const value=ref(40),state=ref('determinate')
const bounded=computed(()=>Math.max(0,Math.min(100,Number(value.value)||0)))
const text=computed(()=>state.value==='indeterminate'?'Working, amount unknown':state.value==='error'?`Paused after an error at ${bounded.value}%`:bounded.value===100?'Sample complete':`${bounded.value}% of sample work`)
function reset(){value.value=40;state.value='determinate'}
</script>
<template><section class="progress-usage" aria-label="Progress usage demonstration"><p>Fictitious local work. No upload or server process runs.</p><label>Sample state<select v-model="state"><option>determinate</option><option>indeterminate</option><option>error</option></select></label><label>Sample percent<input v-model.number="value" type="range" min="0" max="100" :disabled="state==='indeterminate'"></label><label for="progress-guide-bar">{{text}}</label><progress id="progress-guide-bar" max="100" :value="state==='indeterminate'?undefined:bounded"></progress><p role="status">{{text}}</p><div class="actions"><button type="button" :disabled="state==='indeterminate'||bounded===100" @click="value=Math.min(100,bounded+20)">Advance sample by 20</button><button type="button" @click="reset">Reset sample</button></div><div class="comparison"><section><h3>Capacity is a meter</h3><label for="progress-guide-meter">Sample storage used: 65 of 100</label><meter id="progress-guide-meter" min="0" max="100" low="25" high="80" optimum="20" value="65">65%</meter></section><section><h3>Goal ring</h3><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="46" class="track"/><circle cx="60" cy="60" r="46" class="fill" pathLength="100" :stroke-dasharray="`${bounded} 100`" transform="rotate(-90 60 60)"/></svg><p>Sample goal: {{bounded}}% (same local value; not an unknown-progress ring).</p></section></div></section></template>
<style scoped>
.progress-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}label{display:block;margin:14px 0 8px}label:first-of-type{display:flex;align-items:center;gap:12px;flex-wrap:wrap}button,select{min-height:44px;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}input,progress,meter{display:block;width:100%;accent-color:var(--vp-c-brand-1)}progress,meter{height:24px}.actions{display:flex;gap:10px;flex-wrap:wrap}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:24px}.comparison>section{min-width:0}svg{width:140px;max-width:100%;height:auto}circle{fill:none;stroke-width:10}.track{stroke:var(--vp-c-divider)}.fill{stroke:var(--vp-c-brand-1);stroke-linecap:round;transition:stroke-dasharray 180ms ease-out}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@media(max-width:700px){.comparison{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.fill{transition:none}progress:indeterminate{animation:none}}
</style>
